def fill(indent_lvl: int, prefix: str) -> None:
    if indent_lvl > max_depth:
        return
    visited = set()
    for mod_name in list(statistics.keys()):
        # 'if mod' excludes root = '', which is never a child
        if (
            mod_name
            and mod_name.count(".") == prefix.count(".")
            and mod_name.startswith(prefix)
        ):
            if mod_name in visited:
                continue
            visited.add(mod_name)
            new_mod_name, curr_stats = _fastforward(mod_name, statistics)
            if root_prefix and new_mod_name.startswith(root_prefix):
                # Skip the root_prefix shared by all submodules as it carries 0 information
                pretty_mod_name = new_mod_name[len(root_prefix):]
            else:
                pretty_mod_name = new_mod_name
            row = build_row(pretty_mod_name, curr_stats, indent_lvl)
            table.append(row)
            fill(indent_lvl + 1, new_mod_name + ".")
